templates.home:
{{template "top" .}}<section class="hero"><h1>{{.bizName}}</h1>{{with .tagline}}<p class="muted">{{.}}</p>{{end}}</section>
{{range .groups}}<h2>{{.category}}</h2><div class="grid">{{range .services}}<a class="card" href="/s/{{.id}}{{$.q}}">{{if .image}}<div class="img"><img src="{{.image}}?w=640" alt="{{.name}}" loading="lazy"></div>{{end}}
<div class="body"><strong>{{.name}}</strong><p class="muted">{{.description}}</p><div class="price">AED {{.price}}{{if .unitLabel}} <span class="muted">/ {{.unitLabel}}</span>{{end}}</div><span class="btn small">{{$.t.book}}</span></div></a>{{end}}</div>{{end}}
<h2>{{.t.areas}}</h2><div class="chips">{{range .zones}}<span class="chip">{{.name}}{{if .surcharge}} · + AED {{.surcharge}}{{end}}</span>{{end}}</div>
<p class="muted">{{.hours}} · {{.t.vat_included}}</p>
{{template "bottom" .}}

templates.service:
{{template "top" .}}{{with .svc}}<div class="two"><div><h1>{{.name}}</h1><p>{{.description}}</p>
<p class="price" style="font-size:22px">AED {{.price}}{{if .unitLabel}} <span class="muted">/ {{.unitLabel}}</span>{{end}}</p><p class="muted">{{$.t.vat_included}}</p>
{{if .image}}<div class="photo"><img src="{{.image}}?w=960" alt="{{.name}}"></div>{{end}}</div>
<form class="panel" method="get" action="/checkout">{{if $.error}}<p class="error">{{$.error}}</p>{{end}}
<input type="hidden" name="service" value="{{.id}}">{{if eq $.lang "ar"}}<input type="hidden" name="lang" value="ar">{{end}}
{{if .fixed}}<input type="hidden" name="qty" id="qty" value="1">{{else}}<label for="qty">{{$.t.how_many}} ({{.unitLabel}})</label><input id="qty" name="qty" type="number" min="{{.min}}" max="{{.max}}" value="{{.min}}" required>{{end}}
{{if .materials}}<label class="check"><input type="checkbox" name="materials" id="materials" value="1"> {{$.t.materials}} (+ AED {{.materials}}{{if .hourly}} / {{.unitLabel}}{{end}})</label>{{end}}
<label for="zone">{{$.t.area}}</label><select id="zone" name="zone" required>{{range $.zones}}<option value="{{.id}}" data-surcharge="{{.surchargeNum}}">{{.name}}{{if .surcharge}} (+ AED {{.surcharge}}){{end}}</option>{{end}}</select>
<label for="date">{{$.t.date}}</label><select id="date" name="date" required>{{range $.dates}}<option value="{{.}}">{{.}}</option>{{end}}</select>
<label>{{$.t.arrival}}</label><div id="slots" class="slots"></div><p class="muted" id="noslots" hidden>{{$.t.no_slots}}</p>
<label for="repeat">{{$.t.repeat}}</label><select id="repeat" name="repeat"><option value="once">{{$.t.repeat_once}}</option><option value="weekly">{{$.t.repeat_weekly}}</option><option value="every_2_weeks">{{$.t.repeat_every_2_weeks}}</option></select>
<p class="muted" id="repeat-note" hidden>{{$.t.repeat_note}}</p>
<div class="sum"><div class="row"><span>{{.name}}</span><span id="p-service"></span></div><div class="row" id="r-mat" hidden><span>{{$.t.materials}}</span><span id="p-mat"></span></div>
<div class="row" id="r-zone" hidden><span>{{$.t.area_fee}}</span><span id="p-zone"></span></div><div class="row total"><span>{{$.t.total}}</span><span id="p-total"></span></div>
<div class="muted">{{$.t.vat_amount}}: <span id="p-vat"></span></div></div>
<button id="go" disabled>{{$.t.continue}}</button></form></div>{{end}}
<script>
var S={{.calc}},L={{.lang}};
function el(i){return document.getElementById(i)}
function aed(n){return 'AED '+(Math.round(n*100)/100).toFixed(2)}
// A price for display only: the server works the booking out again from its own prices.
function sum(){var q=S.fixed?1:Math.max(S.min,Math.min(S.max,Math.floor(Number(el('qty').value)||S.min)));
 var m=el('materials')&&el('materials').checked?S.materials*(S.hourly?q:1):0,o=el('zone').options[el('zone').selectedIndex],z=o?Number(o.dataset.surcharge)||0:0,t=S.price*q+m+z;
 el('p-service').textContent=aed(S.price*q);el('r-mat').hidden=!m;el('p-mat').textContent=aed(m);el('r-zone').hidden=!z;el('p-zone').textContent=aed(z);
 el('p-total').textContent=aed(t);el('p-vat').textContent=aed(t*5/105);el('repeat-note').hidden=el('repeat').value==='once'}
function slots(){var box=el('slots');box.textContent='';el('go').disabled=true;if(!el('date').value){el('noslots').hidden=false;return}
 fetch('/api/slots?date='+encodeURIComponent(el('date').value)).then(function(r){return r.json()}).then(function(d){var any=false;
  d.slots.forEach(function(s){var l=document.createElement('label'),i=document.createElement('input'),sp=document.createElement('span');
   l.className='slot'+(s.left?'':' off');i.type='radio';i.name='slot';i.value=s.start;i.required=true;i.disabled=!s.left;i.onchange=function(){el('go').disabled=false};
   sp.textContent=s.start+' – '+s.end;l.appendChild(i);l.appendChild(sp);box.appendChild(l);if(s.left)any=true});
  el('noslots').hidden=any})}
Array.prototype.forEach.call(el('date').options,function(o){try{o.textContent=new Date(o.value+'T12:00:00').toLocaleDateString(L==='ar'?'ar-AE':'en-GB',{weekday:'short',day:'numeric',month:'short'})}catch(e){}});
['qty','materials','zone','repeat'].forEach(function(i){if(el(i))el(i).addEventListener('input',sum)});el('date').addEventListener('change',slots);sum();slots();
</script>{{template "bottom" .}}

