<div class="two"><div class="panel">{{with .sel}}<h2>{{.service}}</h2><p>{{.date}} · {{.slot}} – {{.slotEnd}}<br>{{.zone}}{{if .repeatText}}<br>{{.repeatText}}{{end}}</p>
