templates.booking:
{{template "top" .}}{{with .bk}}{{if $.placed}}<p class="ok">{{$.t.thank_you}}</p>{{end}}
<h1>{{$.t.booking}} #{{.id}}</h1><p>{{$.t.status}}: <strong class="badge" id="status">{{.statusText}}</strong></p>
<div id="track"{{if ne .status "on_the_way"}} hidden{{end}}><div id="map"></div><p class="muted" id="seen">{{$.t.crew_coming}}</p></div>
<div class="panel"><h2>{{.service}}</h2><p><strong>{{.date}} · {{.slot}} – {{.slotEnd}}</strong><br>{{.address}}{{if .flat}}, {{.flat}}{{end}}, {{.zone}}{{if .repeatText}}<br>{{.repeatText}}{{end}}{{if .crew}}<br>{{$.t.crew}}: {{.crew}}{{end}}</p>{{if .auto}}<p class="muted">{{$.t.auto_note}}</p>{{end}}
{{range .lines}}<div class="row"><span>{{.name}} × {{.qty}}</span><span>AED {{.amount}}</span></div>{{end}}
{{if .surcharge}}<div class="row"><span>{{$.t.area_fee}}</span><span>AED {{.surcharge}}</span></div>{{end}}
<div class="row total"><span>{{$.t.total}}</span><span>AED {{.total}}</span></div><p class="muted">{{$.t.vat_amount}}: AED {{.vat}} · <span id="payment">{{.paymentText}}</span></p>{{if .refunded}}<p class="ok">{{$.t.refunded_amount}}: AED {{.refunded}}</p>{{end}}
{{if .canPay}}<form method="post" action="/bookings/{{.id}}/pay{{$.q}}"><button>{{$.t.pay_now}}</button></form>{{end}}
{{if .receipt}}<p><a href="/bookings/{{.id}}/receipt{{$.q}}">{{$.t.view_receipt}}</a></p>{{end}}</div>
{{if .photo}}<div class="panel"><h2>{{$.t.photo}}</h2><a href="{{.photo}}" target="_blank" rel="noopener"><img src="{{.photo}}" alt="{{$.t.photo}}" style="max-width:100%;max-height:320px;border-radius:10px"></a></div>{{end}}
{{if .canCancel}}<form class="panel" method="post" action="/bookings/{{.id}}/cancel{{$.q}}"><p class="muted" style="margin-top:0">{{$.cancelNote}}</p>
<button class="secondary" name="later" value="0">{{$.t.cancel_visit}}</button>{{if .repeats}} <button class="secondary" name="later" value="1">{{$.t.cancel_series}}</button>{{end}}</form>{{end}}
{{if .again}}<p><a class="btn" href="/s/{{.serviceId}}{{$.q}}">{{$.t.book_again}}</a></p>{{end}}
{{if .live}}<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
var texts={{$.statusTexts}},start=[{{.lat}},{{.lng}}],has={{.hasPos}},map=null,marker=null,current={{.status}};
function showMap(){document.getElementById('track').hidden=false;if(map||!window.L)return;
 map=L.map('map').setView(has?start:[25.2048,55.2708],has?15:11);
 L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);
 if(has)marker=L.marker(start).addTo(map)}
if(current==='on_the_way')showMap();
// A change that alters the buttons (paid, cancelled, completed) reloads the page, once per status.
function again(s){try{if(sessionStorage.getItem('rx-booking-{{.id}}')===s)return;sessionStorage.setItem('rx-booking-{{.id}}',s)}catch(e){}live.close();location.reload()}
// The crew's page publishes every change to this booking's private channel.
var live=new EventSource('/_rx/live/{{$.channel}}?token='+encodeURIComponent({{$.token}}));
live.onmessage=function(e){var m=JSON.parse(e.data);
 if(m.status&&m.status!==current){if(['pending','confirmed','assigned','on_the_way','in_progress'].indexOf(m.status)<0||current==='pending'){again(m.status);return}
  current=m.status;document.getElementById('status').textContent=texts[m.status]||m.status;
  if(m.status==='on_the_way')showMap();else document.getElementById('track').hidden=true}
 if(typeof m.lat==='number'&&current==='on_the_way'){showMap();if(!map)return;var p=[m.lat,m.lng];
  if(!marker){marker=L.marker(p).addTo(map);map.setView(p,15)}else{marker.setLatLng(p);map.panTo(p)}
  document.getElementById('seen').textContent={{$.t.live_updated}}+' '+new Date().toLocaleTimeString()}};
</script>{{end}}{{end}}{{template "bottom" .}}

scripts.home:
// GET /  services grouped by category, and the areas served
function handle(req) {
  const lang = langOf(req), b = biz(), t = texts(lang);
  const groups = [], index = {};
  for (const s of db.query('SELECT * FROM services WHERE active = 1 ORDER BY id')) {
    const v = serviceView(s, lang);
    if (!(v.category in index)) { index[v.category] = groups.length; groups.push({category: v.category, services: []}); }
    groups[index[v.category]].services.push(v);
  }
  return {template: 'home', data: page(req, {groups: groups, zones: zoneViews(lang),
    hours: t.hours.replace(/\{first\}/g, b.first_slot).replace(/\{last\}/g, b.last_slot)})};
}

scripts.service:
// GET /s/:id  one service with its booking form. The page shows a price for convenience;
// the booking is always priced again on the server.
function handle(req) {
  const lang = langOf(req), b = biz(), t = texts(lang);
  const s = db.query('SELECT * FROM services WHERE id = ? AND active = 1', Number(req.params.id))[0];
  if (!s) return notFound(req);
  const v = serviceView(s, lang);
  return {template: 'service', data: page(req, {svc: v, zones: zoneViews(lang), dates: bookableDates(b), error: errorText(req.query.error, t, b),
    calc: {fixed: v.fixed, hourly: v.hourly, price: s.price, materials: s.materials_price || 0, min: v.min, max: v.max}})};
}

scripts.api_slots:
// GET /api/slots?date=YYYY-MM-DD  the arrival windows of a date with the crews left in each
function handle(req) {
  const b = biz();
  const date = req.query.date || bookableDates(b)[0] || dubaiNow().date;
  return {json: {date: date, closed: dateProblem(date, b), slots: slotsOf(date, b)}};
}

scripts.checkout:
// GET /checkout?service=&qty=&materials=&zone=&date=&slot=&repeat=  (signed in)
// Shows the price worked out on the server and asks for the address and the payment method.
function handle(req) {
  const lang = langOf(req), b = biz(), t = texts(lang), f = req.query;
  if (!f.service) return {redirect: '/' + (lang === 'ar' ? '?lang=ar' : '')};
  const sel = selection(f, b);
  if (sel.error) return {redirect: (sel.svc ? '/s/' + sel.svc.id : '/') + '?error=' + sel.error + (lang === 'ar' ? '&lang=ar' : '')};
  const hidden = [];
  for (const k of ['service', 'qty', 'materials', 'zone', 'date', 'slot', 'repeat']) if (f[k]) hidden.push({name: k, value: f[k]});
  hidden.push({name: 'lang', value: lang});
  return {template: 'checkout', data: page(req, {hidden: hidden, error: errorText(f.error, t, b), card: !!b.card_enabled, cash: !!b.cash_enabled,
    auto: !!b.card_enabled && sel.repeat !== 'once', autoText: sel.repeat === 'once' ? '' : t['pay_auto_' + sel.repeat],
    sel: {serviceId: sel.svc.id, service: pick(sel.svc, 'name', lang), zone: pick(sel.zone, 'name', lang), date: sel.date, slot: sel.slot, slotEnd: sel.slotEnd,
      repeatText: sel.repeat === 'once' ? '' : t['repeat_' + sel.repeat],
      lines: sel.q.lines.map(l => ({name: pick(l, 'name', lang), qty: l.qty, amount: money(l.price * l.qty)})),
      surcharge: sel.q.surcharge > 0 ? money(sel.q.surcharge) : '', total: money(sel.q.total), vat: money(sel.q.vat)}})};
}

scripts.book:
// POST /book  form: service, qty, materials, zone, date, slot, repeat, name, phone, address, flat, notes, photo (an upload id),
// payment (card | cash | auto: card charged automatically for every repeat visit), lang
// The price, the area and the free window always come from the database, never from the browser.
function handle(req) {
  const f = req.form, b = biz();
  const lang = f.lang === 'ar' ? 'ar' : 'en', qa = lang === 'ar' ? '&lang=ar' : '';
  const sel = selection(f, b);
  if (sel.error) return {redirect: (sel.svc ? '/s/' + sel.svc.id : '/') + '?error=' + sel.error + qa};
  const back = '/s/' + sel.svc.id + '?error=';
  const name = (f.name || '').trim(), phone = (f.phone || '').trim(), address = (f.address || '').trim();
  const toCheckout = (error) => {
    const keep = ['service', 'qty', 'materials', 'zone', 'date', 'slot', 'repeat'].filter(k => f[k]).map(k => k + '=' + encodeURIComponent(f[k]));
    return {redirect: '/checkout?' + keep.join('&') + '&error=' + error + qa};
  };
  if (!name || !phone || !address) return toCheckout('error_fields');
  // The photo id comes from the browser: it must be a photo this visitor uploaded.
  let photo = null;
  if (f.photo) {
    const file = files.get(f.photo);
    if (!file || file.user_id !== req.user.id || file.type.indexOf('image/') !== 0) return toCheckout('error_photo');
    photo = file.id;
  }
  const auto = f.payment === 'auto' && !!b.card_enabled && sel.repeat !== 'once';
  let method = auto || (f.payment === 'card' && b.card_enabled) ? 'card' : 'cash';
  if (method === 'cash' && !b.cash_enabled) {
    if (!b.card_enabled) return {redirect: back + 'error_payment' + qa};
    method = 'card';
  }
  // Cash on completion is confirmed at once; a card booking waits for on_payment and holds its window meanwhile.
  const id = insertBooking({user_id: req.user.id, customer_name: name, phone: phone, email: req.user.email || '', zone_id: sel.zone.id, zone: sel.zone.name,
    address: address, flat: (f.flat || '').trim(), notes: (f.notes || '').trim().slice(0, 500), service_id: sel.svc.id, service: sel.svc.name,
    quantity: sel.q.qty, materials: sel.q.materials, date: sel.date, slot: sel.slot, slot_end: sel.slotEnd, repeat: sel.repeat, lines: sel.q.lines,
    subtotal: sel.q.subtotal, surcharge: sel.q.surcharge, vat: sel.q.vat, total: sel.q.total, payment_method: method,
    status: method === 'cash' ? 'confirmed' : 'pending', crew_id: null, lang: lang, parent_id: null, photo: photo, autopay: auto}, b);
  if (!id) return {redirect: back + 'error_slot' + qa};
  if (method === 'cash') {
    const bk = byId(id);
    emailCustomer(bk, 'confirm', req.origin + '/bookings/' + id);
    newBookingNotice(bk, req.origin);
    return {redirect: '/bookings/' + id + '?placed=1' + qa};
  }
  const items = sel.q.lines.map(l => ({name: l.name, price: l.price, quantity: l.qty}));
  if (sel.q.surcharge > 0) items.push({name: 'Area surcharge: ' + sel.zone.name, price: sel.q.surcharge, quantity: 1});
  const done = '/bookings/' + id + '?placed=1' + qa, cancel = '/bookings/' + id + (lang === 'ar' ? '?lang=ar' : '');
  try {
    let pay;
    if (auto) {
      // Every visit of the series is charged to the card: the first now, each later one by a renewal (see on_payment).
      const series = 'series-' + id;
      db.exec('UPDATE bookings SET series = ? WHERE id = ?', series, id);
      pay = payments.subscribe({items: items, interval: 'week', interval_count: sel.repeat === 'weekly' ? 1 : 2, reference: series,
        customer_email: req.user.email || '', success_path: done, cancel_path: cancel});
    } else {
      pay = payments.checkout({items: items, reference: 'booking-' + id, customer_email: req.user.email || '', success_path: done, cancel_path: cancel});
    }
    return {redirect: pay.url};
  } catch (e) {
    console.error('checkout failed for booking ' + id + ': ' + e);
    db.exec("UPDATE bookings SET status = 'failed' WHERE id = ?", id); // frees the window
    return {redirect: back + 'error_payment' + qa};
  }
}

scripts.bookings:
