scripts.crew_status:
// POST /crew/:id/status  form: key, status (on_the_way | in_progress | completed)
// The crew's buttons. Each change reaches the customer's open booking page at once.
function handle(req) {
  const bk = jobFor(req, req.form.key || '');
  if (!bk) return {text: 'unknown job or key', status: 403};
  const to = req.form.status;
  const from = {on_the_way: ['confirmed', 'assigned'], in_progress: ['confirmed', 'assigned', 'on_the_way'], completed: ['on_the_way', 'in_progress']}[to];
  if (!from) return {text: 'unknown status', status: 400};
  if (bk.status === to) return {json: {ok: true, status: to}};
  if (from.indexOf(bk.status) < 0) return {text: 'this job is ' + bk.status, status: 409};
  if (to === 'completed') {
    // Completing a job that was not paid by card means the crew collected the cash.
    db.exec("UPDATE bookings SET status = 'completed', paid = 1 WHERE id = ?", bk.id);
    const crew = bk.crew_id ? db.query('SELECT name FROM crews WHERE id = ?', bk.crew_id)[0] : null;
    tellOwner('Booking #' + bk.id + ' completed' + (crew ? ' by ' + crew.name : '') + (bk.paid ? ', paid by card' : ', cash collected AED ' + money(bk.total)),
      bk.service + ', ' + bk.date + ' ' + bk.slot + '\n' + bk.customer_name + ', ' + bk.address + ', ' + bk.zone);
  } else {
    db.exec('UPDATE bookings SET status = ? WHERE id = ?', to, bk.id);
  }
  live(bk.id, {status: to});
  return {json: {ok: true, status: to}};
}

scripts.crew_position:
// POST /crew/:id/position  form: key, lat, lng
// The crew's phone sends its position while on the way; the customer's map moves at once.
function handle(req) {
  const bk = jobFor(req, req.form.key || '');
  if (!bk) return {text: 'unknown job or key', status: 403};
  if (bk.status !== 'on_the_way') return {text: 'not on the way', status: 409};
  const lat = Number(req.form.lat), lng = Number(req.form.lng);
