}

scripts.on_payment:
// Runs when a card payment is paid, fails, expires or is refunded, and for the automatic payments of a repeating booking.
// req.body: {event, reference, amount, refunded_amount, ...}. References: booking-<id> for one payment;
// series-<id of the first visit> for payments.subscribe: "paid" pays the first visit, each "renewed" pays the next
// visit (booking it now if the daily job has not yet), "renewal_failed" turns the next visit into pay on completion
// or by card from the booking page, "subscription_cancelled" stops the series.
function handle(req) {
  const ref = String(req.body.reference), event = req.body.event, b = biz();
  const series = ref.indexOf('series-') === 0;
  const id = Number(ref.replace(series ? 'series-' : 'booking-', ''));
  const bk = byId(id);
  if (!bk) return {text: 'ignored'};
  if (series && event === 'renewed') {
    const v = seriesVisit(ref, b);
    if (!v) {
      tellOwner('Automatic payment AED ' + money(req.body.amount) + ' for repeat booking #' + id + ' has no visit to pay',
        'The next visit of ' + bk.customer_name + ' (' + bk.phone + ') could not be booked. Book it in the admin panel, or refund the payment on the Payments page.');
      return {text: 'no visit'};
    }
    db.exec("UPDATE bookings SET paid = 1, autopay = 1, payment_method = 'card', pay_ref = ? WHERE id = ?", ref, v.bk.id);
    if (v.created) emailCustomer(byId(v.bk.id), 'repeat_auto', req.origin + '/bookings/' + v.bk.id);
    console.log('booking ' + v.bk.id + ' paid by the automatic payment of ' + ref);
    return {text: 'ok'};
  }
  if (series && event === 'renewal_failed') {
    // Stripe retries a failed charge: tell the customer once, and a later success still pays this visit.
    const v = seriesVisit(ref, b);
    if (!v) {
      tellOwner('Automatic card payment failed for repeat booking #' + id + ' (' + bk.customer_name + ')', 'There is no upcoming visit to collect it for.\n' + bk.customer_name + ', ' + bk.phone);
      return {text: 'no visit'};
    }
    if (!v.bk.autopay) return {text: 'already told'};
    db.exec("UPDATE bookings SET autopay = 0, paid = 0, payment_method = 'cash' WHERE id = ?", v.bk.id);
    const now = byId(v.bk.id);
    emailCustomer(now, 'payment_failed', req.origin + '/bookings/' + now.id);
    tellOwner('Automatic card payment failed for booking #' + now.id + ': ' + now.service + ', ' + now.date + ' ' + now.slot + ', AED ' + money(now.total) + ' to collect',
      'The customer was emailed a link to pay by card; otherwise the crew collects cash.\n' + now.customer_name + ', ' + now.phone);
    return {text: 'ok'};
  }
  if (series && event === 'subscription_cancelled') {
    db.exec("UPDATE bookings SET autopay = 0, payment_method = 'cash' WHERE series = ? AND paid = 0 AND autopay = 1 AND status IN ('confirmed', 'assigned')", ref);
    db.exec('UPDATE bookings SET repeat_done = 1 WHERE series = ?', ref);
    const open = db.query("SELECT COUNT(*) AS n FROM bookings WHERE series = ? AND status IN ('confirmed', 'assigned')", ref)[0].n;
    if (open) tellOwner('Automatic payments ended for repeat booking #' + id + ' (' + bk.customer_name + ')',
      'No more visits will be booked. ' + open + ' visit(s) already booked are now paid on completion.\n' + bk.customer_name + ', ' + bk.phone);
    console.log('series ' + ref + ' ended');
    return {text: 'ok'};
  }
  if (event === 'refunded' || event === 'partially_refunded') {
    // A series' refunds are recorded on the visit by the script that made them (cancel, admin_change).
    if (series) { console.log(ref + ' ' + event + ' ' + req.body.refunded_amount); return {text: 'ok'}; }
    if (event === 'refunded') {
      // A refunded booking no longer holds its window.
      db.exec("UPDATE bookings SET status = CASE status WHEN 'cancelled' THEN 'cancelled' ELSE 'refunded' END, paid = 0, refunded = ? WHERE id = ?", req.body.refunded_amount, id);
      live(id, {status: byId(id).status});
    } else {
      db.exec('UPDATE bookings SET refunded = ? WHERE id = ?', req.body.refunded_amount, id); // the visit stands
    }
    console.log('booking ' + id + ' ' + event + ' ' + req.body.refunded_amount);
    return {text: 'ok'};
  }
  if (event === 'paid') {
    if (bk.paid) return {text: 'ignored'};
    if (bk.status === 'pending') {
      db.exec("UPDATE bookings SET status = 'confirmed', paid = 1, payment_method = 'card', pay_ref = ? WHERE id = ?", ref, id);
      const now = byId(id);
      emailCustomer(now, 'confirm', req.origin + '/bookings/' + id);
      newBookingNotice(now, req.origin);
      live(id, {status: 'confirmed'});
    } else {
      // An unpaid cash visit (for example a repeat visit) paid by card from the booking page.
      db.exec("UPDATE bookings SET paid = 1, payment_method = 'card', pay_ref = ? WHERE id = ?", ref, id);
      tellOwner('Booking #' + id + ' paid by card: AED ' + money(bk.total) + ', nothing to collect', bk.service + ', ' + bk.date + ' ' + bk.slot + '\n' + bk.customer_name);
    }
  } else if (bk.status === 'pending' && (event === 'failed' || event === 'expired')) {
    // Failed or expired: the booking stops holding its arrival window.
    db.exec('UPDATE bookings SET status = ? WHERE id = ?', event, id);
    live(id, {status: event});
  }
  console.log('booking ' + id + ' payment ' + event);
  return {text: 'ok'};
}

scripts.daily:
// Job, every evening:
// 1. books the next visit of weekly and 2-weekly bookings as soon as its date can be booked (same window). Visits of
//    a series paid automatically wait for their card charge (on_payment pays them on each renewal); others are paid on
//    completion and the customer is emailed a link to pay by card or cancel.
//    When the window is full or closed the visit is skipped and the owner is told.
// 2. emails customers a reminder of tomorrow's visit.
// 3. sends the owner tomorrow's jobs per crew.
function handle(req) {
  const b = biz(), today = dubaiNow().date, tomorrow = addDays(today, 1), horizon = addDays(today, b.days_ahead || 14);
  const due = db.query(`SELECT * FROM bookings WHERE repeat IN ('weekly', 'every_2_weeks') AND coalesce(repeat_done, 0) = 0
    AND status IN ('confirmed', 'assigned', 'on_the_way', 'in_progress', 'completed', 'cancelled')
    AND date(date, CASE repeat WHEN 'weekly' THEN '+7 days' ELSE '+14 days' END) <= ? ORDER BY date, id LIMIT 12`, horizon);
  let made = 0;
  const skipped = [];
  for (const p of due) {
    const n = bookNext(p, b);
    if (!n.id) {
      skipped.push('#' + p.id + ' ' + p.customer_name + ' (' + p.phone + '), ' + p.service + ', ' + n.date + ' ' + p.slot + ': ' + n.problem);
      continue;
    }
    made++;
    emailCustomer(byId(n.id), p.series ? 'repeat_auto' : 'repeat', req.origin + '/bookings/' + n.id);
  }

  const visits = db.query("SELECT * FROM bookings WHERE date = ? AND status IN ('confirmed', 'assigned') ORDER BY slot, id LIMIT 60", tomorrow);
  let reminded = 0;
  for (const v of visits) {
    if (v.reminded || !v.email || reminded >= 40) continue;
    emailCustomer(v, 'reminder', req.origin + '/bookings/' + v.id);
    db.exec('UPDATE bookings SET reminded = 1 WHERE id = ?', v.id);
    reminded++;
  }

  const summary = made + ' repeat visits booked, ' + skipped.length + ' skipped, ' + reminded + ' reminders, ' + visits.length + ' visits tomorrow';
  if (!visits.length && !made && !skipped.length) return {text: summary};
  const crews = {};
  for (const c of db.query('SELECT id, name, phone FROM crews')) crews[c.id] = c.name + (c.phone ? ' (' + c.phone + ')' : '');
  const groups = {}, order = [];
  let unassigned = 0;
  for (const v of visits) {
    const who = v.crew_id && crews[v.crew_id] ? crews[v.crew_id] : 'NO CREW ASSIGNED';
    if (who === 'NO CREW ASSIGNED') unassigned++;
    if (!groups[who]) { groups[who] = []; order.push(who); }
    groups[who].push(v.slot + ' - ' + v.slot_end + '  #' + v.id + ' ' + v.service + ' x ' + v.quantity + '\n  ' + v.customer_name + ', ' + v.phone + '\n  ' +
      v.address + (v.flat ? ', ' + v.flat : '') + ', ' + v.zone + '\n  ' + (v.paid ? 'paid' : v.autopay ? 'card charged automatically' : 'collect AED ' + money(v.total)) +
      '\n  ' + req.origin + '/crew/' + v.id + '?key=' + v.crew_key);
  }
  let text = order.map(who => who + '\n' + groups[who].join('\n')).join('\n\n') || 'No visits tomorrow.';
  if (made) text += '\n\nRepeat visits booked today: ' + made;
  if (skipped.length) text += '\n\nRepeat visits NOT booked, please call the customer:\n' + skipped.join('\n');
  tellOwner('Tomorrow ' + tomorrow + ': ' + visits.length + ' visit' + (visits.length === 1 ? '' : 's') + (unassigned ? ', ' + unassigned + ' without a crew' : '') +
    (made ? ', ' + made + ' repeat booked' : '') + (skipped.length ? ', ' + skipped.length + ' repeat skipped' : ''), text);
  return {text: summary};
}

