scripts.mcp_quote:
// MCP tool: the price of a visit, worked out exactly as the booking form does.
function handle(req) {
  const b = biz(), a = req.body;
  const svc = db.query('SELECT * FROM services WHERE id = ? AND active = 1', Number(a.service_id))[0];
  if (!svc) return {text: 'unknown service_id; call list_services', status: 400};
  const name = String(a.area || '').trim().toLowerCase();
  const zone = db.query('SELECT * FROM zones WHERE active = 1 ORDER BY id').find(z => String(z.id) === name || z.name.toLowerCase() === name || (z.name_ar || '') === String(a.area || '').trim());
  if (!zone) return {text: 'we do not serve this area; call list_services for the areas', status: 400};
  const q = quote(svc, a.quantity === undefined || a.quantity === null ? (svc.min_qty || 1) : a.quantity, zone, a.materials === true, b);
  if (q.error === 'error_minimum') return {text: 'below the minimum order of AED ' + money(b.min_order), status: 400};
  if (q.error) return {text: 'quantity must be between ' + (svc.min_qty || 1) + ' and ' + (svc.max_qty || 99), status: 400};
  return {json: {currency: 'AED', service: svc.name, area: zone.name, quantity: q.qty, unit: svc.unit === 'fixed' ? null : svc.unit_label,
    lines: q.lines.map(l => ({name: l.name, unit_price: l.price, quantity: l.qty, amount: round2(l.price * l.qty)})),
    subtotal: q.subtotal, area_surcharge: q.surcharge, total: q.total, vat_included: q.vat,
    payment_methods: [b.card_enabled ? 'card' : null, b.cash_enabled ? 'cash on completion' : null].filter(Boolean), book_url: req.origin + '/s/' + svc.id}};
}

scripts.mcp_business:
